-- Lam's FINAL query, submitted 2026-10-19.
-- Original line breaks from the chat archive were not preserved;
-- the SQL text is otherwise unchanged.

WITH lesson_completed AS (SELECT enrollment_id, COUNT(completion_id) FROM lesson_completions GROUP BY enrollment_id), enroll_full_info AS (SELECT e.enrollment_id, c.title, c.category, e.student_id, e.enrolled_at, e.status, l.count FROM enrollments e LEFT JOIN lesson_completed l ON e.enrollment_id = l.enrollment_id LEFT JOIN courses c ON c.course_id = e.course_id WHERE e.enrolled_at >= '2026-09-01' AND e.enrolled_at < '2026-10-01' AND e.status = 'active'), metrics AS (SELECT category, title, COUNT(enrollment_id) sept_enrollments, COUNT(student_id) unique_students, SUM(count) lessons_completed, ROUND(SUM(count) / COUNT(enrollment_id),1) avg_lessons_per_enrollment FROM enroll_full_info GROUP BY category, title) SELECT c.title, c.category, COALESCE(m.sept_enrollments,0) sept_enrollments, COALESCE(m.unique_students,0) unique_students, COALESCE(m.lessons_completed,0) lessons_completed, m.avg_lessons_per_enrollment, RANK() OVER (PARTITION BY c.category ORDER BY COALESCE(m.unique_students,0) DESC) category_rank FROM courses c LEFT JOIN metrics m ON m.title = c.title AND m.category = c.category ORDER BY c.category ASC, category_rank ASC, c.title ASC;
